local PlantClimbingNetMaker = {}
local PRODUCTS = {
    iron_plantclimbingnet = { name = "Železni mreže za plezalke", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni mreže za plezalke za vrtnarje." },
    bronze_plantclimbingnet = { name = "Bronast mreže za plezalke", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast mreže za plezalke za vrtnarje." },
    silver_plantclimbingnet = { name = "Srebrn mreže za plezalke", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn mreže za plezalke za vrtnarje." },
    gilded_plantclimbingnet = { name = "Pozlačen mreže za plezalke", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen mreže za plezalke za vrtnarje." },
    jewel_set_plantclimbingnet = { name = "Draguljast mreže za plezalke", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast mreže za plezalke za vrtnarje." },
    royal_sovereign_plantclimbingnet = { name = "Kraljevski suveren mreže za plezalke", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren mreže za plezalke z biseri za krono." },
}
local BUILDINGS = {
    plantclimbingnet_workshop = { name = "Plantclimbingnet delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    plantclimbingnet_house = { name = "Plantclimbingnet hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_plantclimbingnet_atelier = { name = "Mojstrski plantclimbingnet atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_plantclimbingnet_palace = { name = "Suverena plantclimbingnet palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
PlantClimbingNetMaker.ironStock=12; PlantClimbingNetMaker.bronzeStock=10; PlantClimbingNetMaker.woodStock=16; PlantClimbingNetMaker.leatherStock=10; PlantClimbingNetMaker.silverStock=8; PlantClimbingNetMaker.goldStock=6; PlantClimbingNetMaker.jewelStock=4; PlantClimbingNetMaker.pearlStock=4
PlantClimbingNetMaker.productStock = {}; PlantClimbingNetMaker.buildings = {}; PlantClimbingNetMaker.maker = nil; PlantClimbingNetMaker.activeMaking = {}; PlantClimbingNetMaker.totalProducts = 0; PlantClimbingNetMaker.dayTimer = 0
function PlantClimbingNetMaker.init() PlantClimbingNetMaker.ironStock=12; PlantClimbingNetMaker.bronzeStock=10; PlantClimbingNetMaker.woodStock=16; PlantClimbingNetMaker.leatherStock=10; PlantClimbingNetMaker.silverStock=8; PlantClimbingNetMaker.goldStock=6; PlantClimbingNetMaker.jewelStock=4; PlantClimbingNetMaker.pearlStock=4; PlantClimbingNetMaker.productStock={}; PlantClimbingNetMaker.buildings={}; PlantClimbingNetMaker.maker=nil; PlantClimbingNetMaker.activeMaking={}; PlantClimbingNetMaker.totalProducts=0; PlantClimbingNetMaker.dayTimer=0; print("[PlantClimbingNetMaker] Royal Plant Climbing Net Maker System initialized (6 products, 4 buildings)") end
function PlantClimbingNetMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlantClimbingNetMaker.maker={name=n or ("Mrežar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mrežar najet: %s (spretnost: %d)",PlantClimbingNetMaker.maker.name,s),"success") end; return true end
function PlantClimbingNetMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlantClimbingNetMaker.build(id) local ok,e=PlantClimbingNetMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlantClimbingNetMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlantClimbingNetMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlantClimbingNetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlantClimbingNetMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PlantClimbingNetMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PlantClimbingNetMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PlantClimbingNetMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PlantClimbingNetMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PlantClimbingNetMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlantClimbingNetMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlantClimbingNetMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlantClimbingNetMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlantClimbingNetMaker.buildings==0 then return false,"Potrebna mrezna delavnica" end; if not PlantClimbingNetMaker.maker then return false,"Potreben mrezar" end; return true end
function PlantClimbingNetMaker.make(pt,qty) qty=qty or 1; local ok,e=PlantClimbingNetMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PlantClimbingNetMaker.ironStock=PlantClimbingNetMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PlantClimbingNetMaker.bronzeStock=PlantClimbingNetMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PlantClimbingNetMaker.woodStock=PlantClimbingNetMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PlantClimbingNetMaker.leatherStock=PlantClimbingNetMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PlantClimbingNetMaker.silverStock=PlantClimbingNetMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlantClimbingNetMaker.goldStock=PlantClimbingNetMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlantClimbingNetMaker.jewelStock=PlantClimbingNetMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlantClimbingNetMaker.pearlStock=PlantClimbingNetMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlantClimbingNetMaker.maker then t=math.max(1,t-math.floor(PlantClimbingNetMaker.maker.skill/13)) end; table.insert(PlantClimbingNetMaker.activeMaking,{id="plantclimbingnet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlantClimbingNetMaker.completeMaking(m) local q=1.0+(PlantClimbingNetMaker.getQualityBonus()/100); if PlantClimbingNetMaker.maker then q=q+(PlantClimbingNetMaker.maker.skill/140) end; q=math.min(2.5,q); PlantClimbingNetMaker.productStock[m.productType]=(PlantClimbingNetMaker.productStock[m.productType] or 0)+m.quantity; PlantClimbingNetMaker.totalProducts=PlantClimbingNetMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlantClimbingNetMaker.maker then PlantClimbingNetMaker.maker.itemsMade=PlantClimbingNetMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PlantClimbingNetMaker.maker.skill=math.min(100,PlantClimbingNetMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mreža izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"plantclimbingnet.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PlantClimbingNetMaker.update(dt) if not _G.state then return end; PlantClimbingNetMaker.dayTimer=PlantClimbingNetMaker.dayTimer+dt; if PlantClimbingNetMaker.dayTimer>=30 then PlantClimbingNetMaker.dayTimer=0; for i=#PlantClimbingNetMaker.activeMaking,1,-1 do local m=PlantClimbingNetMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlantClimbingNetMaker.completeMaking(m); table.remove(PlantClimbingNetMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlantClimbingNetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlantClimbingNetMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlantClimbingNetMaker.getStats() return {ironStock=PlantClimbingNetMaker.ironStock,bronzeStock=PlantClimbingNetMaker.bronzeStock,woodStock=PlantClimbingNetMaker.woodStock,leatherStock=PlantClimbingNetMaker.leatherStock,silverStock=PlantClimbingNetMaker.silverStock,goldStock=PlantClimbingNetMaker.goldStock,jewelStock=PlantClimbingNetMaker.jewelStock,pearlStock=PlantClimbingNetMaker.pearlStock,productStock=PlantClimbingNetMaker.productStock,numBuildings=#PlantClimbingNetMaker.buildings,hasMaker=PlantClimbingNetMaker.maker~=nil,makerName=PlantClimbingNetMaker.maker and PlantClimbingNetMaker.maker.name or "—",makerSkill=PlantClimbingNetMaker.maker and PlantClimbingNetMaker.maker.skill or 0,activeMaking=#PlantClimbingNetMaker.activeMaking,totalProducts=PlantClimbingNetMaker.totalProducts} end
return PlantClimbingNetMaker
